    ON CAST(n.id_hit_high AS STRING) = CAST(i.id_hit_high AS STRING)
   AND CAST(n.id_hit_low AS STRING) = CAST(i.id_hit_low AS STRING)
)
SELECT
  COUNTIF(CAST(n_accept_language AS STRING) IS DISTINCT FROM CAST(i_accept_language AS STRING)) AS `accept_language`,
  COUNTIF(CAST(n_id_browser AS STRING) IS DISTINCT FROM CAST(i_id_browser AS STRING)) AS `id_browser`,
  COUNTIF(CAST(n_carrier AS STRING) IS DISTINCT FROM CAST(i_carrier AS STRING)) AS `carrier`,
  COUNTIF(CAST(n_des_color_depth AS STRING) IS DISTINCT FROM CAST(i_des_color_depth AS STRING)) AS `des_color_depth`,
  COUNTIF(CAST(n_cod_version AS STRING) IS DISTINCT FROM CAST(i_cod_version AS STRING)) AS `cod_version`,
  COUNTIF(CAST(n_id_color AS STRING) IS DISTINCT FROM CAST(i_id_color AS STRING)) AS `id_color`,
  COUNTIF(CAST(n_id_connection_type AS STRING) IS DISTINCT FROM CAST(i_id_connection_type AS STRING)) AS `id_connection_type`,
  COUNTIF(CAST(n_id_country AS STRING) IS DISTINCT FROM CAST(i_id_country AS STRING)) AS `id_country`,
  COUNTIF(CAST(n_connection_type AS STRING) IS DISTINCT FROM CAST(i_connection_type AS STRING)) AS `connection_type`,
  COUNTIF(CAST(n_currency_type AS STRING) IS DISTINCT FROM CAST(i_currency_type AS STRING)) AS `currency_type`,
  COUNTIF(CAST(n_flg_daily_visitor AS STRING) IS DISTINCT FROM CAST(i_flg_daily_visitor AS STRING)) AS `flg_daily_visitor`,
